python3 -c "
import yaml
doc = yaml.safe_load(open('.github/workflows/ci.yml'))
jobs = doc['jobs']
def needs_of(jid):
    n = jobs.get(jid, {}).get('needs', [])
    return [n] if isinstance(n, str) else list(n)
closure = set()
def collect(name):
    if name in closure: return
    closure.add(name)
    for n in needs_of(name): collect(n)
collect('quality-gate')
def coe_excluded(j):
    v = j.get('continue-on-error')
    return v is True or str(v).lower() == 'true'
def runs_on_tag(j):
    t = str(j.get('if', '') or '')
    return (not t.strip()) or ('github.event_name' not in t) or (\"== 'push'\" in t)
derived = {jid for jid, j in jobs.items()
           if jid != 'ci-red-report' and jid not in closure
           and not coe_excluded(j) and runs_on_tag(j)}
covered = set(needs_of('ci-red-report'))
pinned = {'binaries','integration','js-ext-integration','publish','watchdog','step-timings','faui-coverage',
          'release-provenance','release-asset-smoke','installer-smoke','install-pin-bump','train-draft-guard'}
ifclause = jobs['ci-red-report']['if']
checks = {
  'derived == pinned 12-leg set': derived == pinned,
  'covered covers quality-gate + derived': covered.issuperset({'quality-gate'} | derived),
  'every covered leg has direct failure clause': all(\"needs.%s.result == 'failure'\" % l in ifclause for l in covered),
  'documented exclusions stay excluded': not ({'release','binaries-pr','binaries-smoke-gate','web-spa','build-extension','release-pending'} & derived),
  'push gate + always() preserved': \"github.event_name == 'push'\" in ifclause and 'always()' in ifclause,
  'no event_name negations in file': \"!= 'push'\" not in open('.github/workflows/ci.yml').read(),
  'bite: drop publish -> gap detected': not {'quality-gate'} | derived <= (covered - {'publish'}),
}
for k, v in checks.items(): print(('PASS' if v else 'FAIL'), '-', k)
assert all(checks.values())
print('ALL DERIVATION CHECKS PASS on head', open('.git/HEAD').read().strip())
"

